[EFFECT 2]
TYPE: EFFECT_TYPE_CONTINUOUS, EFFECT_TYPE_FIELD | CAT: NONE
CODE: EFFECT_DESTROY_REPLACE | PROP: NONE
RANGE: LOCATION_FZONE | LIMIT: 1
FLOW: Duel.IsExistingMatchingCard -> LOCATION_DECK -> Duel.SelectEffectYesNo -> REASON_BATTLE -> Duel.Hint -> Duel.SelectMatchingCard -> Duel.SendtoGrave -> REASON_EFFECT
-- TARGET:
function s.destg(e,tp,eg,ep,ev,re,r,rp,chk)
	if chk==0 then return eg:IsExists(s.dfilter,1,nil,tp)
		and Duel.IsExistingMatchingCard(s.repfilter,tp,LOCATION_DECK,0,1,nil) end
	return Duel.SelectEffectYesNo(tp,e:GetHandler(),96)
end
-- [Filter/Helper: s.repfilter]
function s.repfilter(c)
	return c:IsRace(RACE_ROCK) and c:IsAbleToGrave()
end
-- [Filter/Helper: s.dfilter]
function s.dfilter(c,tp)
	return c:IsControler(tp) and c:IsReason(REASON_BATTLE)
end
-- OPERATION:
function s.desop(e,tp,eg,ep,ev,re,r,rp)
	Duel.Hint(HINT_SELECTMSG,tp,HINTMSG_TOGRAVE)
	local g=Duel.SelectMatchingCard(tp,s.repfilter,tp,LOCATION_DECK,0,1,1,nil)
	Duel.SendtoGrave(g,REASON_EFFECT)
end
-- [Filter/Helper: s.repfilter]
function s.repfilter(c)
	return c:IsRace(RACE_ROCK) and c:IsAbleToGrave()
end

[EFFECT 4]
TYPE: EFFECT_TYPE_IGNITION | CAT: CATEGORY_TOGRAVE, CATEGORY_SPECIAL_SUMMON
CODE: NONE | PROP: NONE
RANGE: LOCATION_HAND | LIMIT: 1,{id,1}
FLOW: Duel.IsExistingMatchingCard -> LOCATION_PZONE -> Duel.GetLocationCount -> LOCATION_MZONE -> LOCATION_HAND -> LOCATION_EXTRA -> Duel.SetOperationInfo -> Duel.Hint -> Duel.SelectMatchingCard -> Duel.SendtoGrave -> REASON_EFFECT -> LOCATION_GRAVE -> Duel.SpecialSummon -> POS_FACEUP
-- CONDITION:
function s.spcon(e,tp,eg,ep,ev,re,r,rp)
	return Duel.IsExistingMatchingCard(s.spconfilter,tp,LOCATION_PZONE,0,1,nil)
end
-- [Filter/Helper: s.spconfilter]
function s.spconfilter(c)
	return c:IsSetCard(SET_SUPREME_KING_GATE) and not c:IsCode(id)
end
-- TARGET:
function s.sptg(e,tp,eg,ep,ev,re,r,rp,chk)
	local c=e:GetHandler()
	if chk==0 then return Duel.GetLocationCount(tp,LOCATION_MZONE)>0
		and c:IsCanBeSpecialSummoned(e,0,tp,false,false)
		and Duel.IsExistingMatchingCard(s.tgfilter,tp,LOCATION_HAND|LOCATION_EXTRA,0,1,c) end
	Duel.SetOperationInfo(0,CATEGORY_TOGRAVE,nil,1,tp,LOCATION_EXTRA)
	Duel.SetOperationInfo(0,CATEGORY_SPECIAL_SUMMON,c,1,0,0)
end
-- [Filter/Helper: s.tgfilter]
function s.tgfilter(c)
	return c:IsSetCard({SET_PENDULUM_DRAGON,SET_XYZ_DRAGON,SET_SYNCHRO_DRAGON,SET_FUSION_DRAGON}) and c:IsAbleToGrave()
end
-- OPERATION:
function s.spop(e,tp,eg,ep,ev,re,r,rp)
	local c=e:GetHandler()
	Duel.Hint(HINT_SELECTMSG,tp,HINTMSG_TOGRAVE)
	local tc=Duel.SelectMatchingCard(tp,s.tgfilter,tp,LOCATION_HAND|LOCATION_EXTRA,0,1,1,c):GetFirst()
	if tc and Duel.SendtoGrave(tc,REASON_EFFECT)>0 and tc:IsLocation(LOCATION_GRAVE)
		and c:IsRelateToEffect(e) then
		Duel.SpecialSummon(c,0,tp,tp,false,false,POS_FACEUP)
	end
end
-- [Filter/Helper: s.tgfilter]
function s.tgfilter(c)
	return c:IsSetCard({SET_PENDULUM_DRAGON,SET_XYZ_DRAGON,SET_SYNCHRO_DRAGON,SET_FUSION_DRAGON}) and c:IsAbleToGrave()
end

psct_text:
If you have no Spell/Trap Cards in your Graveyard, you can Special Summon this card (from your hand). After this card was Special Summoned this way, you cannot Special Summon monsters for the rest of this turn, except "Superheavy Samurai" monsters. You can Tribute this card, then activate 1 of these effects;
● Destroy 1 card in your opponent's Spell & Trap Zone, then you can Set the destroyed Spell/Trap Card on your side of the field.
● Destroy 1 card in your opponent's Pendulum Zone, then you can place the destroyed card in your Pendulum Zone.

effects.canonical_effect_str:
[EFFECT 3]
TYPE: NONE | CAT: NONE
CODE: EVENT_MSET | PROP: NONE
RANGE: NONE | LIMIT: NONE
FLOW: PASSIVE
-- CONDITION:
function s.spcon2(e,tp,eg,ep,ev,re,r,rp)
	return eg:IsExists(s.filter2,1,nil,tp)
