[EFFECT 2]
TYPE: EFFECT_TYPE_FIELD, EFFECT_TYPE_CONTINUOUS | CAT: NONE
CODE: EFFECT_DESTROY_REPLACE | PROP: NONE
RANGE: LOCATION_GRAVE | LIMIT: 1,{id,1}
FLOW: Duel.SelectEffectYesNo -> REASON_REPLACE -> REASON_EFFECT -> REASON_BATTLE -> Duel.Remove -> POS_FACEUP
-- TARGET:
function s.reptg(e,tp,eg,ep,ev,re,r,rp,chk)
	local c=e:GetHandler()
	if chk==0 then return c:IsAbleToRemove() and eg:IsExists(s.repfilter,1,nil,tp) end
	return Duel.SelectEffectYesNo(tp,c,96)
end
-- [Filter/Helper: s.repfilter]
function s.repfilter(c,tp)
	return c:IsFaceup() and c:IsControler(tp) and c:IsOnField() and c:IsSetCard(SET_SALAMANGREAT)
		and not c:IsReason(REASON_REPLACE) and c:IsReason(REASON_EFFECT|REASON_BATTLE)
end
-- OPERATION:
function s.repop(e,tp,eg,ep,ev,re,r,rp)
	Duel.Remove(e:GetHandler(),POS_FACEUP,REASON_EFFECT|REASON_REPLACE)
end

[EFFECT 1]
TYPE: EFFECT_TYPE_SINGLE | CAT: NONE
CODE: EFFECT_CANNOT_BE_BATTLE_TARGET | PROP: EFFECT_FLAG_SINGLE_RANGE
RANGE: LOCATION_MZONE | LIMIT: NONE
FLOW: Duel.IsExistingMatchingCard -> LOCATION_MZONE
-- CONDITION:
function s.atklm(e)
	return Duel.IsExistingMatchingCard(s.atkfilter,e:GetHandlerPlayer(),LOCATION_MZONE,0,1,nil)
end
-- [Filter/Helper: s.atkfilter]
function s.atkfilter(c)
	return c:IsFacedown() or (c:IsFaceup() and not c:IsType(TYPE_TUNER))
end

[EFFECT 3]
TYPE: EFFECT_TYPE_QUICK_O | CAT: CATEGORY_RELEASE, CATEGORY_SPECIAL_SUMMON
CODE: EVENT_BE_BATTLE_TARGET | PROP: NONE
RANGE: LOCATION_MZONE | LIMIT: 1,{id,1}
FLOW: Duel.GetMatchingGroup -> LOCATION_MZONE -> Duel.IsExistingMatchingCard -> LOCATION_HAND -> LOCATION_DECK -> Duel.SetOperationInfo -> Duel.GetMZoneCount -> Duel.Release -> REASON_EFFECT -> Duel.GetLocationCount -> Duel.Hint -> Duel.SelectMatchingCard -> Duel.SpecialSummon -> POS_FACEUP
-- TARGET:
function s.sptg(e,tp,eg,ep,ev,re,r,rp,chk)
	local g=Duel.GetMatchingGroup(s.cfilter,tp,LOCATION_MZONE,LOCATION_MZONE,nil,tp)
	if chk==0 then return #g>=2 and Duel.IsExistingMatchingCard(s.spfilter,tp,LOCATION_HAND|LOCATION_DECK,0,1,nil,e,tp)
		and aux.SelectUnselectGroup(g,e,tp,2,2,s.rescon,0) end
	Duel.SetOperationInfo(0,CATEGORY_RELEASE,g,2,0,0)
	Duel.SetOperationInfo(0,CATEGORY_SPECIAL_SUMMON,nil,1,tp,LOCATION_HAND|LOCATION_DECK)
end
-- [Filter/Helper: s.spfilter]
function s.spfilter(c,e,tp)
	return c:IsSetCard(SET_NOUVELLES) and c:IsRitualMonster() and c:IsLevel(5,6)
		and c:IsCanBeSpecialSummoned(e,0,tp,false,true)
end
-- [Filter/Helper: s.rescon]
function s.rescon(sg,e,tp,mg)
	return Duel.GetMZoneCount(tp,sg)>0 and sg:IsExists(s.atkposchk,1,nil,sg,tp)
end
-- [Filter/Helper: s.cfilter]
function s.cfilter(c,tp)
	return c:IsReleasableByEffect() and (s.selfnouvfilter(c,tp) or c:IsAttackPos())
end
-- [Filter/Helper: s.atkposchk]
function s.atkposchk(c,sg,tp)
	return c:IsAttackPos() and sg:IsExists(s.selfnouvfilter,1,c,tp)
end
-- [Filter/Helper: s.selfnouvfilter]
function s.selfnouvfilter(c,tp)
	return c:IsControler(tp) and c:IsSetCard(SET_NOUVELLES)
end
-- OPERATION:
function s.spop(e,tp,eg,ep,ev,re,r,rp)
	local g=Duel.GetMatchingGroup(s.cfilter,tp,LOCATION_MZONE,LOCATION_MZONE,nil,tp)
	if #g<2 then return end
	local rg=aux.SelectUnselectGroup(g,e,tp,2,2,s.rescon,1,tp,HINTMSG_RELEASE)
	if Duel.Release(rg,REASON_EFFECT)==2 and Duel.GetLocationCount(tp,LOCATION_MZONE)>0 then
		Duel.Hint(HINT_SELECTMSG,tp,HINTMSG_SPSUMMON)
		local g=Duel.SelectMatchingCard(tp,s.spfilter,tp,LOCATION_HAND|LOCATION_DECK,0,1,1,nil,e,tp)
		if #g>0 then
			Duel.SpecialSummon(g,0,tp,tp,false,true,POS_FACEUP)
		end
	end
end
-- [Filter/Helper: s.rescon]
function s.rescon(sg,e,tp,mg)
	return Duel.GetMZoneCount(tp,sg)>0 and sg:IsExists(s.atkposchk,1,nil,sg,tp)
end
-- [Filter/Helper: s.spfilter]
function s.spfilter(c,e,tp)
	return c:IsSetCard(SET_NOUVELLES) and c:IsRitualMonster() and c:IsLevel(5,6)
		and c:IsCanBeSpecialSummoned(e,0,tp,false,true)
end
-- [Filter/Helper: s.cfilter]
function s.cfilter(c,tp)
	return c:IsReleasableByEffect() and (s.selfnouvfilter(c,tp) or c:IsAttackPos())
end
-- [Filter/Helper: s.atkposchk]
function s.atkposchk(c,sg,tp)
	return c:IsAttackPos() and sg:IsExists(s.selfnouvfilter,1,c,tp)
end
-- [Filter/Helper: s.selfnouvfilter]
function s.selfnouvfilter(c,tp)
	return c:IsControler(tp) and c:IsSetCard(SET_NOUVELLES)
end

psct_text:
Once per turn: You can Ritual Summon 1 WIND Ritual Monster from your Deck, by Tributing Spirit monsters and/or "Shinobird Token(s)" from your field, whose total Levels equal or exceed the Ritual Monster's Level. Twice per turn, if a face-up WIND monster(s) you control is returned to your hand (except during the Damage Step): You can activate 1 of these effects;
● Add 1 of your Spirit monsters or Ritual Spells that is banished or in your GY to your hand.
● Set 1 "Stars Align across the Milky Way" directly from your Deck.

effects.canonical_effect_str:
[EFFECT 2]
TYPE: EFFECT_TYPE_SINGLE | CAT: NONE
CODE: EFFECT_INDESTRUCTABLE_BATTLE | PROP: EFFECT_FLAG_SINGLE_RANGE
RANGE: LOCATION_MZONE | LIMIT: NONE
FLOW: Duel.IsExistingMatchingCard -> LOCATION_ONFIELD
-- CONDITION:
function s.indcon(e)
	return Duel.IsExistingMatchingCard(s.tknfilter,e:GetHandlerPlayer(),LOCATION_ONFIELD,0,1,nil)
end
-- [Filter/Helper: s.tknfilter]
function s.tknfilter(c)
	return c:IsType(TYPE_TOKEN) or c:IsOriginalType(TYPE_TOKEN)
end

[EFFECT 6]
TYPE: EFFECT_TYPE_SINGLE | CAT: NONE
CODE: EFFECT_CANNOT_ATTACK | PROP: NONE
RANGE: NONE | LIMIT: NONE
FLOW: Duel.IsExistingMatchingCard -> LOCATION_GRAVE
-- CONDITION:
function s.atcon(e)
	return Duel.IsExistingMatchingCard(s.atfilter,e:GetHandlerPlayer(),LOCATION_GRAVE,0,1,nil)
end
-- [Filter/Helper: s.atfilter]
function s.atfilter(c)
	return not c:IsSetCard(SET_MECHA_PHANTOM_BEAST) and c:IsMonster()
end

[EFFECT 2]
TYPE: EFFECT_TYPE_FIELD, EFFECT_TYPE_TRIGGER_O | CAT: NONE
CODE: EVENT_REMOVE | PROP: NONE
RANGE: LOCATION_MZONE | LIMIT: NONE
FLOW: PASSIVE
-- CONDITION:
function s.attachcon(e,tp,eg,ep,ev,re,r,rp)
	return eg:IsExists(s.trapfilter,1,nil,tp)
end
-- [Filter/Helper: s.trapfilter]
function s.trapfilter(c,tp)
	return c:IsTrap() and c:IsFaceup() and c:IsOwner(tp)
end

[EFFECT 4]
TYPE: EFFECT_TYPE_QUICK_O | CAT: CATEGORY_TOHAND, CATEGORY_SPECIAL_SUMMON
CODE: EVENT_FREE_CHAIN | PROP: NONE
RANGE: LOCATION_SZONE | LIMIT: 1
FLOW: Duel.IsExistingMatchingCard -> LOCATION_HAND -> Duel.DiscardHand -> REASON_COST -> REASON_DISCARD -> Duel.GetLocationCount -> LOCATION_MZONE -> LOCATION_GRAVE -> Duel.SetOperationInfo -> Duel.SetPossibleOperationInfo -> Duel.Hint -> Duel.SelectMatchingCard -> Duel.SpecialSummon -> POS_FACEUP
-- COST:
function s.spcost(e,tp,eg,ep,ev,re,r,rp,chk)
	if chk==0 then return Duel.IsExistingMatchingCard(Card.IsDiscardable,tp,LOCATION_HAND,0,1,e:GetHandler()) end
	Duel.DiscardHand(tp,Card.IsDiscardable,1,1,REASON_COST|REASON_DISCARD)
end
-- TARGET:
function s.sptg(e,tp,eg,ep,ev,re,r,rp,chk)
	local ft=Duel.GetLocationCount(tp,LOCATION_MZONE)
	if chk==0 then return Duel.IsExistingMatchingCard(s.filter,tp,LOCATION_GRAVE,0,1,nil,e,tp,ft) end
	Duel.SetOperationInfo(0,CATEGORY_LEAVE_GRAVE,nil,1,tp,0)
	Duel.SetPossibleOperationInfo(0,CATEGORY_TOHAND,nil,1,tp,LOCATION_GRAVE)
	Duel.SetPossibleOperationInfo(0,CATEGORY_SPECIAL_SUMMON,nil,1,tp,LOCATION_GRAVE)
end
-- [Filter/Helper: s.filter]
function s.filter(c,e,tp,ft)
	return c:IsCode(6007213 --[[Uria, Lord of Searing Flames]],32491822 --[[Hamon, Lord of Striking Thunder]],69890967 --[[Raviel, Lord of Phantasms]]) and (c:IsAbleToHand() or (ft>0 and c:IsCanBeSpecialSummoned(e,0,tp,true,false)))
end
-- OPERATION:
function s.spop(e,tp,eg,ep,ev,re,r,rp)
	local ft=Duel.GetLocationCount(tp,LOCATION_MZONE)
	Duel.Hint(HINT_SELECTMSG,tp,aux.Stringid(id,2))
	local hc=Duel.SelectMatchingCard(tp,s.filter,tp,LOCATION_GRAVE,0,1,1,nil,e,tp,ft):GetFirst()
	if not hc then return end
	aux.ToHandOrElse(hc,tp,
		function()
			return Duel.GetLocationCount(tp,LOCATION_MZONE)>0 and hc:IsCanBeSpecialSummoned(e,0,tp,true,false)
		end,
		function()
			Duel.SpecialSummon(hc,0,tp,tp,true,false,POS_FACEUP)
		end,
		aux.Stringid(id,3)
