CODE: EVENT_SUMMON_SUCCESS | PROP: EFFECT_FLAG_DELAY
RANGE: NONE | LIMIT: 1,{id,1}
FLOW: Duel.IsExistingMatchingCard -> LOCATION_DECK -> Duel.SetOperationInfo -> Duel.SetPossibleOperationInfo -> LOCATION_GRAVE -> Duel.Hint -> Duel.SelectMatchingCard -> Duel.SendtoHand -> REASON_EFFECT -> Duel.ConfirmCards -> Duel.GetLocationCount -> LOCATION_MZONE -> Duel.SelectYesNo -> Duel.BreakEffect -> Duel.SpecialSummon -> POS_FACEUP
